import React, { useState, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [isRecording, setIsRecording] = useState(false); // 녹음 상태 관리
  const [error, setError] = useState(null);
  const chatEndRef = useRef(null);

  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);

  // 마이크 녹음 시작
  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      
      mediaRecorderRef.current.ondataavailable = event => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
        sendAudioToBackend(audioBlob); // 녹음이 끝난 후 서버로 전송
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error('Error accessing microphone', err);
      setError('마이크에 접근할 수 없습니다.');
    }
  };

  // 녹음 중지
  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  // 음성을 서버로 전송하는 함수
  const sendAudioToBackend = async (audioBlob) => {
    const formData = new FormData();
    formData.append('audio', audioBlob, 'audio.mp3');

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/stt`, {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error('음성 인식 오류');
      }

      const data = await response.json();
      setUserInput(data.transcript); // 음성 텍스트화된 데이터
    } catch (err) {
      console.error('Error sending audio:', err);
      setError('음성 전송 실패');
    }
  };

  // 텍스트로 챗봇에게 입력
  const handleSubmit = async (event) => {
    event.preventDefault();
    if (userInput.trim() === '') return;

    const newChatHistory = [
      ...chatHistory,
      { sender: 'user', message: userInput },
    ];

    setChatHistory(newChatHistory);

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_input: userInput, personality, chatbotName }),
      });

      const result = await response.json();

      setChatHistory([
        ...newChatHistory,
        { sender: 'chatbot', message: result.response },
      ]);
      setUserInput('');
    } catch (error) {
      console.error('Error fetching chatbot response:', error);
      setError('서버 오류');
    }
  };

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatHistory}>
        {chatHistory.map((chat, idx) => (
          <div key={idx} className={chat.sender === 'user' ? styles.userMessage : styles.chatbotMessage}>
            {chat.message}
          </div>
        ))}
      </div>

      <div className={styles.inputContainer}>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          placeholder="Type your message"
          className={styles.inputField}
        />
        <button onClick={handleSubmit} className={styles.submitButton}>Send</button>

        {/* 음성 녹음 버튼 */}
        <button onClick={isRecording ? stopRecording : startRecording} className={styles.voiceButton}>
          {isRecording ? 'Stop' : 'Record'}
        </button>
      </div>
      
      {error && <div className={styles.error}>{error}</div>}
      
      <div ref={chatEndRef} />
    </div>
  );
};

export default Chat;
